#include <vector>
#include <cstddef>
#include <stdexcept>
#include <omp.h>

int maxDegree(std::vector<int> const& A, size_t N) {
    if (N == 0) {
        return 0;
    }

    // Validate that A is an N x N matrix without risking overflow in N * N.
    if ((A.size() % N) != 0 || (A.size() / N) != N) {
        throw std::invalid_argument("A must contain exactly N*N elements.");
    }

    int max_degree = 0;

    #pragma omp parallel for reduction(max:max_degree) schedule(static)
    for (std::ptrdiff_t i = 0; i < static_cast<std::ptrdiff_t>(N); ++i) {
        int row_degree = 0;
        const size_t row_start = static_cast<size_t>(i) * N;

        for (size_t j = 0; j < N; ++j) {
            row_degree += (A[row_start + j] != 0) ? 1 : 0;
        }

        if (row_degree > max_degree) {
            max_degree = row_degree;
        }
    }

    return max_degree;
}
